"""Generate the per-reservoir public expansion report from actual audit outputs."""
import json,hashlib
from backend.config import ROOT,DATA
from backend.monitoring import reservoirs
from backend.active import monitoring
original=json.loads((DATA/'internal/original-eight-coverage-snapshot.json').read_text())
rows=reservoirs();batch=json.loads((ROOT/'output/coverage-batch-results.json').read_text());audit=json.loads((ROOT/'output/coverage-admission-audit.json').read_text());ui=json.loads((ROOT/'output/public-frontend-state-verification.json').read_text())
lines=['# Functional Karnataka reservoir coverage expansion','','## Outcome',f'Public operational reservoirs: {len(rows)} (original eight preserved; {len(rows)-8} admitted after preprocessing).',f"Internal pending records: {len(json.loads((DATA/'internal/pending-reservoirs.json').read_text()))}.",'No ordinary tanks, forecasting, redesign, concentration substitution or relaxed quality masks were added.','', '## Actual results','','| Reservoir | Boundary | Earlier acquisition | Latest acquisition | Latest chlorophyll-a µg/L | Change % | EPA category | RGB | Chlorophyll map |','|---|---|---|---|---:|---:|---|---|---|']
for r in rows:
 m=monitoring(r['id']);assert m['change'];lines.append(f"| {r['name']} | [Verified polygon]({r['osm_url']}) | {m['previous']['observed_at'][:10]} | {m['latest']['observed_at'][:10]} | {m['chlorophyll_a']:.2f} | {m['change']['percent']:+.2f} | {m['classification']['name']} | PASS | PASS |")
lines+=['','Both dates use the existing Gilerson 2010 two-band Sentinel-2 L2A BOA screening method, matching atmospheric correction and 60 m grid, shoreline/cloud exclusions, positive-reflectance checks, minimum 25 pixels/10% coverage and 1–100 µg/L project algorithm screening range. Concentrations are medians of valid pixels. The concentration, RGB and chlorophyll map use the same acquisition.','', '## Government identity verification','','Government records used: [Central Water Commission NRLD 2019](https://www.cwc.gov.in/sites/default/files/nrld-2019.pdf) and [Karnataka Legislative Assembly questions, 18 July 2016](https://kla.kar.nic.in/assembly/questions/lasq18072016.pdf) for Markonahalli. Government inventory dam locations were independently compared to the original OpenStreetMap reservoir water polygons. Names, PICs, physical PDF pages and distances are saved in data/internal/coverage-identity-audit.json. These government dam points were not used as fabricated water boundaries.','','## New-reservoir validation','','| New reservoir | Identity / polygon | Two spectral calculations / rasters | Comparable pair / EPA | Live API | React / Leaflet sessions | Visual inspection |','|---|---|---|---|---|---|']
for r in rows:
 if r['id'] in original:continue
 assert len([x for x in ui if x['reservoir']==r['id']])==2
 lines.append(f"| {r['name']} | PASS | PASS | PASS | PASS | PASS | INCOMPLETE: browser disabled |")
lines+=['','## Candidate failures and exclusions','']
for b in batch:
 if b.get('error'):lines.append('- '+b['id']+': '+b['error'])
 elif not b.get('readiness',{}).get('ready'):lines.append('- '+b['id']+': '+str(b.get('readiness')))
lines+=['','Basava Sagara spans multiple Sentinel-2 tiles; its best single-tile footprint is about 89.2%, below the unchanged 95% required footprint. It remains pending. No partial-reservoir estimate was published as a whole-reservoir value.','Kodasalli and Karanja remain unadmitted: project water polygons and processed pairs have not been verified. Nugu and Kadra were attempted after the first eight candidates to compensate for footprint failures. Admission stopped within the requested 15–20 operational range.','','## Real verification','','- Original eight latest/history/boundary file hashes preserved byte-for-byte (tests/test_coverage_integrity.py).','- Each newly admitted pair was independently recomputed from its saved B04/B05 arrays; median, valid pixel count, raster pixels, scene ID and CRS matched. Both source arrays contain real SCL water pixels overlapping the polygon.','- All public API details, true-colour images, chlorophyll maps, boundaries and PDF downloads checked. Pending IDs remain HTTP 404.','- The actual React bundle and Leaflet run against the real localhost API in two fresh jsdom sessions, loading every public workspace, matching concentrations and verifying polygon SVGs, named popups and click callbacks. These are frontend state tests, not visual browser tests.','- Backend restarted and the checks repeated against persisted data.','- Backend suite: 53 passed, with one existing Starlette/httpx deprecation warning. Frontend production build passed.','','## Evidence and changed files','','- data/reservoirs.json — only audited public additions.','- data/internal/pending-reservoirs.json — excluded candidates retained with reasons.','- data/internal/coverage-identity-audit.json — official identity/location audit.','- data/internal/original-eight-coverage-snapshot.json — original output preservation hashes.','- data/sentinel2/{new reservoir}/* — genuine two-date bands, masks, manifests, PNGs and GeoTIFFs.','- scripts/expand_verified_coverage.py — sequential small-batch preprocessing.','- scripts/expand_additional_candidates.py — Nugu/Kadra sequential follow-up batch.','- data/boundaries/nugu.geojson and data/boundaries/kadra.geojson — real sourced OpenStreetMap polygons.','- scripts/audit_candidate_identities.py — government record/polygon matching.','- scripts/admit_coverage_candidates.py — independent spectral-pair checks before admission.','- scripts/report_coverage_expansion.py — this generated report.','- tests/test_coverage_integrity.py — original-eight preservation and new identity/readiness checks.','- tests/test_sentinel2.py — operational count now permits the requested 15–20 range.','- output/coverage-batch-results.json and output/coverage-admission-audit.json — candidate outcomes.','- output/processing-verification.json and output/public-frontend-state-verification.json — live API/spectral and React/Leaflet evidence.','','## Limitations','','Browser control remains disabled in Work settings, so final visual layout and geographic-overlay inspection are incomplete. No claim of full visual validation is made. The served application is local at http://127.0.0.1:8010; no remote production deployment was changed.','','Satellite-derived chlorophyll-a estimates have not yet been validated against Karnataka field measurements. Full aquatic atmospheric correction/local calibration remain absent; these experimental surface-reflectance estimates and EPA trophic categories are not confirmed harmful-bloom or toxicity alerts.']
(ROOT/'output/coverage-expansion-report.md').write_text('\n'.join(lines)+'\n')
print('Report generated',len(rows))
